use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::Array(items) = input {
        let mut total = 0;
        for item in items {
            if let Value::Array(sub_items) = item {
                if let [Value::Number(unit_price_cents), Value::Number(quantity)] = sub_items.as_slice() {
                    if let (Some(unit_price_cents), Some(quantity)) = (unit_price_cents.as_i64(), quantity.as_i64()) {
                        total += unit_price_cents * quantity;
                    }
                }
            }
        }
        Value::Number(serde_json::Number::from(total))
    } else {
        Value::Null
    }
}
